// Test how SPARC64 passes and returns packed structs.

// The ABI does not say how packed structs are passed, and GCC passes them
// entirely in integer registers. Clang 23 and before did not treat packed
// structs differently for the ABI, and FPRs were used instead.
// See also https://github.com/llvm/llvm-project/issues/39500.

struct packed_float_int {
  float f;
  int i;
} __attribute__((packed));

// CHECK-LABEL: define dso_local i64 @test_packed_float_int(
// CHECK-SAME: i64 [[X_COERCE:%.*]]) #[[ATTR0:[0-9]+]] {
// CHECK-NEXT:  [[ENTRY:.*:]]
// CHECK-NEXT:    [[RETVAL:%.*]] = alloca [[STRUCT_PACKED_FLOAT_INT:%.*]], align 1
// CHECK-NEXT:    [[X:%.*]] = alloca [[STRUCT_PACKED_FLOAT_INT]], align 1
// CHECK-NEXT:    store i64 [[X_COERCE]], ptr [[X]], align 1
// CHECK-NEXT:    call void @llvm.memcpy.p0.p0.i64(ptr align 1 [[RETVAL]], ptr align 1 [[X]], i64 8, i1 false)
// CHECK-NEXT:    [[TMP0:%.*]] = load i64, ptr [[RETVAL]], align 1
// CHECK-NEXT:    ret i64 [[TMP0]]
//
struct packed_float_int test_packed_float_int(struct packed_float_int x) {
  return x;
}

