// Being packed carries into a nested struct.
struct inner_float {
  float f;
};

struct packed_outer {
  struct inner_float inner;
  float g;
} __attribute__((packed));

// CHECK-LABEL: define dso_local i64 @test_packed_outer(
// CHECK-SAME: i64 [[X_COERCE:%.*]]) #[[ATTR0]] {
// CHECK-NEXT:  [[ENTRY:.*:]]
// CHECK-NEXT:    [[RETVAL:%.*]] = alloca [[STRUCT_PACKED_OUTER:%.*]], align 1
// CHECK-NEXT:    [[X:%.*]] = alloca [[STRUCT_PACKED_OUTER]], align 1
// CHECK-NEXT:    store i64 [[X_COERCE]], ptr [[X]], align 1
// CHECK-NEXT:    call void @llvm.memcpy.p0.p0.i64(ptr align 1 [[RETVAL]], ptr align 1 [[X]], i64 8, i1 false)
// CHECK-NEXT:    [[TMP0:%.*]] = load i64, ptr [[RETVAL]], align 1
// CHECK-NEXT:    ret i64 [[TMP0]]
//
struct packed_outer test_packed_outer(struct packed_outer x) { return x; }

// But adjacent fields are not affected when the attribute is on the struct.
struct packed_inner {
  float f;
} __attribute__((packed));

struct plain_outer {
  struct packed_inner inner;
  float g;
};

// CHECK-LABEL: define dso_local inreg { i32, float } @test_plain_outer(
// CHECK-SAME: i32 inreg [[X_COERCE0:%.*]], float inreg [[X_COERCE1:%.*]]) #[[ATTR0]] {
// CHECK-NEXT:  [[ENTRY:.*:]]
// CHECK-NEXT:    [[RETVAL:%.*]] = alloca [[STRUCT_PLAIN_OUTER:%.*]], align 4
// CHECK-NEXT:    [[X:%.*]] = alloca [[STRUCT_PLAIN_OUTER]], align 4
// CHECK-NEXT:    [[TMP0:%.*]] = getelementptr inbounds nuw { i32, float }, ptr [[X]], i32 0, i32 0
// CHECK-NEXT:    store i32 [[X_COERCE0]], ptr [[TMP0]], align 4
// CHECK-NEXT:    [[TMP1:%.*]] = getelementptr inbounds nuw { i32, float }, ptr [[X]], i32 0, i32 1
// CHECK-NEXT:    store float [[X_COERCE1]], ptr [[TMP1]], align 4
// CHECK-NEXT:    call void @llvm.memcpy.p0.p0.i64(ptr align 4 [[RETVAL]], ptr align 4 [[X]], i64 8, i1 false)
// CHECK-NEXT:    [[TMP2:%.*]] = load { i32, float }, ptr [[RETVAL]], align 4
// CHECK-NEXT:    ret { i32, float } [[TMP2]]
//
struct plain_outer test_plain_outer(struct plain_outer x) { return x; }

// A packed field makes its struct packed.
struct packed_field {
  float f __attribute__((packed));
  int i;
};

// CHECK-LABEL: define dso_local i64 @test_packed_field(
// CHECK-SAME: i64 [[X_COERCE:%.*]]) #[[ATTR0]] {
// CHECK-NEXT:  [[ENTRY:.*:]]
// CHECK-NEXT:    [[RETVAL:%.*]] = alloca [[STRUCT_PACKED_FIELD:%.*]], align 4
// CHECK-NEXT:    [[X:%.*]] = alloca [[STRUCT_PACKED_FIELD]], align 4
// CHECK-NEXT:    store i64 [[X_COERCE]], ptr [[X]], align 4
// CHECK-NEXT:    call void @llvm.memcpy.p0.p0.i64(ptr align 4 [[RETVAL]], ptr align 4 [[X]], i64 8, i1 false)
// CHECK-NEXT:    [[TMP0:%.*]] = load i64, ptr [[RETVAL]], align 4
// CHECK-NEXT:    ret i64 [[TMP0]]
//
struct packed_field test_packed_field(struct packed_field x) { return x; }

// So unlike the attribute on a struct not affecting adjacent fields, the attribute on a field does
// cause all adjacent fields to be passed via GPRs.
struct packed_field_sibling {
  float a;
  float b __attribute__((packed));
};

struct packed_field_sibling
// CHECK-LABEL: define dso_local i64 @test_packed_field_sibling(
// CHECK-SAME: i64 [[X_COERCE:%.*]]) #[[ATTR0]] {
// CHECK-NEXT:  [[ENTRY:.*:]]
// CHECK-NEXT:    [[RETVAL:%.*]] = alloca [[STRUCT_PACKED_FIELD_SIBLING:%.*]], align 4
// CHECK-NEXT:    [[X:%.*]] = alloca [[STRUCT_PACKED_FIELD_SIBLING]], align 4
// CHECK-NEXT:    store i64 [[X_COERCE]], ptr [[X]], align 4
// CHECK-NEXT:    call void @llvm.memcpy.p0.p0.i64(ptr align 4 [[RETVAL]], ptr align 4 [[X]], i64 8, i1 false)
// CHECK-NEXT:    [[TMP0:%.*]] = load i64, ptr [[RETVAL]], align 4
// CHECK-NEXT:    ret i64 [[TMP0]]
//
test_packed_field_sibling(struct packed_field_sibling x) {
  return x;
}

