// Only the packed attribute counts, #pragma pack changes the alignment, but not the ABI.
#pragma pack(1)
struct pragma_packed {
  float f;
  int i;
};
#pragma pack()

// CHECK-LABEL: define dso_local inreg %struct.pragma_packed @test_pragma_packed(
// CHECK-SAME: float inreg [[X_COERCE0:%.*]], i32 inreg [[X_COERCE1:%.*]]) #[[ATTR0]] {
// CHECK-NEXT:  [[ENTRY:.*:]]
// CHECK-NEXT:    [[RETVAL:%.*]] = alloca [[STRUCT_PRAGMA_PACKED:%.*]], align 1
