// CHECK-NEXT:    store i32 [[X_COERCE1]], ptr [[TMP1]], align 1
// CHECK-NEXT:    call void @llvm.memcpy.p0.p0.i64(ptr align 1 [[RETVAL]], ptr align 1 [[X]], i64 8, i1 false)
